          name: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          placeholder: "Alex Morgan",
          required: true
        },
        {
          id: "email-address",
          name: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          placeholder: "alex@example.com",
          required: true
        },
        {
          id: "phone-number",
          name: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          placeholder: "+1 555 123 4567",
          required: false,
          helperText: "Use international format, for example +1 555 123 4567."
        }
      ];

      function Field({ id, name, label, type, autocomplete, placeholder, required, helperText }) {
        const helperId = helperText ? `${id}-helper` : "";
        const describedBy = helperId ? ` aria-describedby="${helperId}"` : "";
        const requiredLabel = required
          ? ' <span class="required-note" aria-hidden="true">*</span>'
          : ' <span class="required-note">(optional)</span>';
        const requiredAttribute = required ? " required" : "";
        const helper = helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : "";

        return `
          <div class="form-field">
            <label for="${id}">${label}${requiredLabel}</label>
            <input
              id="${id}"
              name="${name}"
              type="${type}"
              autocomplete="${autocomplete}"
              placeholder="${placeholder}"
              ${requiredAttribute}
              ${describedBy}
            >
            ${helper}
          </div>
        `;
      }

      function ContactForm() {
        return `
          <section class="card" aria-labelledby="contact-form-title">
            <h2 class="form-title" id="contact-form-title">Tell us how to reach you</h2>
