<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: light;
        --color-page: #f6f8fb;
        --color-surface: #ffffff;
        --color-text: #172033;
        --color-muted: #4b5870;
        --color-border: #b8c2d2;
        --color-border-strong: #66758d;
        --color-primary: #155eef;
        --color-primary-hover: #0f49c7;
        --color-focus: #8b3dff;
        --color-error: #b42318;
        --color-success: #157347;
        --shadow-card: 0 24px 60px #d7deeb;
      }

      * {
        box-sizing: border-box;
      }

      html {
        min-width: 320px;
      }

      body {
        min-height: 100vh;
        margin: 0;
        background:
          radial-gradient(circle at top left, #dbeafe 0, transparent 34rem),
          linear-gradient(135deg, var(--color-page), #eef2f7);
        color: var(--color-text);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        background: var(--color-text);
        color: var(--color-surface);
        padding: 0.75rem 1rem;
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--color-focus);
      }

      .site-header {
        padding: 2rem clamp(1rem, 4vw, 4rem) 0;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.65rem;
        color: var(--color-text);
        font-size: 1rem;
        font-weight: 800;
        letter-spacing: -0.02em;
      }

      .brand-mark {
        display: inline-grid;
        width: 2rem;
        height: 2rem;
        place-items: center;
        border-radius: 0.7rem;
        background: var(--color-primary);
        color: var(--color-surface);
      }

      main {
        width: min(100%, 72rem);
        margin: 0 auto;
        padding: clamp(2rem, 6vw, 5rem) clamp(1rem, 4vw, 4rem) 4rem;
      }

      .support-layout {
        display: grid;
        grid-template-columns: minmax(0, 0.95fr) minmax(18rem, 1.05fr);
        gap: clamp(1.5rem, 5vw, 4rem);
        align-items: center;
      }

      .eyebrow {
        margin: 0 0 1rem;
        color: var(--color-primary);
        font-size: 0.8rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        max-width: 12ch;
        margin: 0;
        font-size: clamp(2.5rem, 7vw, 5rem);
        line-height: 0.95;
        letter-spacing: -0.07em;
      }

      .intro {
        max-width: 34rem;
        margin: 1.5rem 0 0;
        color: var(--color-muted);
        font-size: clamp(1rem, 2vw, 1.18rem);
      }

      .support-note {
        display: grid;
        gap: 0.35rem;
        max-width: 30rem;
        margin-top: 2rem;
        padding: 1rem 1.1rem;
        border: 1px solid var(--color-border);
        border-radius: 1.25rem;
        background: #ffffff;
      }

      .support-note strong {
        font-size: 0.95rem;
      }

      .support-note span {
        color: var(--color-muted);
      }

      .card {
        width: 100%;
        min-width: 0;
        border: 1px solid #d5dceb;
        border-radius: 1.75rem;
        background: var(--color-surface);
        box-shadow: var(--shadow-card);
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .form-title {
        margin: 0;
        font-size: 1.5rem;
        line-height: 1.2;
        letter-spacing: -0.03em;
      }

      .form-description {
        margin: 0.5rem 0 1.5rem;
        color: var(--color-muted);
      }

      .contact-form {
        display: grid;
        gap: 1.1rem;
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
      }

      label {
        color: var(--color-text);
        font-weight: 700;
      }

      .required-note {
        color: var(--color-muted);
        font-weight: 600;
      }

      input {
        width: 100%;
        min-height: 3.15rem;
        border: 1px solid var(--color-border-strong);
        border-radius: 0.9rem;
        background: #ffffff;
        color: var(--color-text);
        font: inherit;
        padding: 0.8rem 0.95rem;
      }

      input::placeholder {
        color: #65738a;
      }

      input:hover {
        border-color: #46556d;
      }

      input:focus-visible,
      button:focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--color-focus);
      }

      input[aria-invalid="true"] {
        border-color: var(--color-error);
      }

      .helper-text {
        margin: 0;
        color: var(--color-muted);
        font-size: 0.92rem;
      }

      .error-text {
        margin: 0;
        color: var(--color-error);
        font-size: 0.92rem;
        font-weight: 700;
      }

      .submit-button {
        min-height: 3.2rem;
        margin-top: 0.35rem;
        border: 0;
        border-radius: 999px;
        background: var(--color-primary);
        color: var(--color-surface);
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        letter-spacing: -0.01em;
      }

      .submit-button:hover {
        background: var(--color-primary-hover);
      }

      .submit-button:active {
        transform: translateY(1px);
      }

      .form-status {
        min-height: 1.5rem;
        margin: 0.25rem 0 0;
        color: var(--color-success);
        font-weight: 700;
      }

      @media (max-width: 48rem) {
        .support-layout {
          grid-template-columns: 1fr;
        }

        h1 {
          max-width: 15ch;
        }
      }

      @media (forced-colors: active) {
        body,
        .card,
        .support-note {
          background: Canvas;
          color: CanvasText;
        }

        .brand-mark,
        .submit-button,
        .skip-link {
          border: 1px solid ButtonBorder;
          background: ButtonFace;
          color: ButtonText;
        }

        input {
          border-color: ButtonBorder;
          background: Field;
          color: FieldText;
        }

        input:focus-visible,
        button:focus-visible,
        .skip-link:focus {
          outline: 3px solid Highlight;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <header class="site-header" data-component="PageHeader">
      <div class="brand" aria-label="Support portal">
        <span class="brand-mark" aria-hidden="true">S</span>
        <span>Support Portal</span>
      </div>
    </header>

    <main id="main-content" data-component="SupportPage">
      <div class="support-layout">
        <section aria-labelledby="page-title" data-component="SupportHero">
          <p class="eyebrow">Support contact</p>
          <h1 id="page-title">How can we help?</h1>
          <p class="intro">
            Send us your details and we will route your request to the right specialist.
            Required fields are marked with an asterisk.
          </p>
          <p class="support-note">
            <strong>Response time</strong>
            <span>Most requests receive a reply within one business day.</span>
          </p>
        </section>

        <section class="card" aria-labelledby="contact-form-title" data-component="ContactForm">
          <h2 class="form-title" id="contact-form-title">Tell us how to reach you</h2>
          <p class="form-description">Share your contact details and our support team will follow up.</p>
          <form class="contact-form" id="support-contact-form" novalidate>
            <div class="form-field" data-component="FormField">
              <label for="full-name">Full name <span class="required-note" aria-hidden="true">*</span></label>
              <input
                id="full-name"
                name="fullName"
                type="text"
                autocomplete="name"
                placeholder="Alex Morgan"
                required
              >
            </div>

            <div class="form-field" data-component="FormField">
              <label for="email-address">Email address <span class="required-note" aria-hidden="true">*</span></label>
              <input
                id="email-address"
                name="email"
                type="email"
                autocomplete="email"
                placeholder="alex@example.com"
                required
              >
            </div>

            <div class="form-field" data-component="FormField">
              <label for="phone-number">Phone number <span class="required-note">(optional)</span></label>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                autocomplete="tel"
                placeholder="+1 555 123 4567"
                aria-describedby="phone-number-helper"
              >
              <p class="helper-text" id="phone-number-helper">Use international format, for example +1 555 123 4567.</p>
            </div>

            <button class="submit-button" type="submit">Submit support request</button>
            <p class="form-status" id="form-status" aria-live="polite"></p>
          </form>
        </section>
      </div>
    </main>

    <script>
      const form = document.getElementById("support-contact-form");
      const status = document.getElementById("form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const invalidField = Array.from(form.elements).find(
          (element) => element.matches?.("input[required]") && !element.value.trim()
        );

        form.querySelectorAll("input").forEach((input) => {
          input.setAttribute("aria-invalid", input === invalidField ? "true" : "false");
        });

        if (invalidField) {
          status.textContent = "Complete the required fields before submitting.";
          status.style.color = "var(--color-error)";
          invalidField.focus();
          return;
        }

        status.textContent = "Thanks. Your support request is ready to send.";
        status.style.color = "var(--color-success)";
        form.reset();
        form.querySelectorAll("input").forEach((input) => input.removeAttribute("aria-invalid"));
      });
    </script>
  </body>
</html>
